import { copyFileSync, constants, existsSync } from 'node:fs';
import { createRequire } from 'node:module';
import { resolve } from 'node:path';

// Format/size conversion only; artwork and transparency are generated by ImageGen.
const sharp = createRequire(import.meta.url)(process.argv[2] || 'sharp');
const source = 'C:/Users/PC/.codex/generated_images/01a10afd-83a1-7c81-af3f-374a5152688b/exec-9cd2821b-bf0b-49f2-8a4d-d75d4ae485ca.png';
const master = resolve('public/assets/xianxia/props/about-scholar-scroll.png');
if (!existsSync(master)) copyFileSync(source, master, constants.COPYFILE_EXCL);
const output = await sharp(master).resize({ width: 800, withoutEnlargement: true })
  .webp({ quality: 83, alphaQuality: 92 }).toFile(resolve('public/assets/xianxia/props/about-scholar-scroll.webp'));
console.log(output);
